import { HubDiscovery } from '../../services/HubDiscovery';
import { findHub } from '../../library/HubClient';
import { createLibraryLaunchUrl } from '../../library/browserLaunch';
import { isPidAlive } from '../../utils/pid';
import { ProjectLibrary } from '../../services/ProjectLibrary';
import { errorResult, okResult, type CliCommandResult } from '../envelope';
import { integerFlag, stringFlag } from '../flags';
import type { CliIO } from '../io';
import { isCommandResult, parseCommandContext } from './shared';
import { initiatorFor } from '../handoff';
import { writeSessionHandoff } from '../handoffStore';
import { explicitRunnerSelectionError } from '../runnerSelection';
import { errorMessage } from '../../utils/errorMessage';
import { getPluginName } from '../../hosts/pluginContext';

const COMMAND = '__serve';

const SERVE_FLAG_SPEC = {
  'rivet-port': { takesValue: true },
  'user-port': { takesValue: true },
  framework: { takesValue: true },
  entry: { takesValue: true },
  'style-framework': { takesValue: true },
  'tailwind-config': { takesValue: true },
  debug: { takesValue: false },
  agent: { takesValue: true },
  'no-git': { takesValue: false },
};

export const handleServe = async (
  args: string[],
  io: CliIO,
): Promise<CliCommandResult> => {
  const context = parseCommandContext(COMMAND, args, SERVE_FLAG_SPEC);
  if (isCommandResult(context)) {
    return context;
  }
  const { flags, projectPath, handoff } = context;
  if (flags.values.debug === true) {
    process.env.LOG_LEVEL = 'DEBUG';
    const { setLogLevel } = await import('../../utils/logger');
    setLogLevel('DEBUG');
  }

  const { CliLogForwarder } = await import('../../services/CliLogForwarder');
  const logForwarder = new CliLogForwarder({
    enabled: flags.values['no-telemetry'] !== true,
  });
  logForwarder.init();

  const { ensureLoginShellPath } = await import('../../utils/loginShellPath');
  ensureLoginShellPath();

  const agentSelectionError = explicitRunnerSelectionError(
    stringFlag(flags, 'agent'),
  );
  if (agentSelectionError) {
    await logForwarder.shutdown();
    return errorResult(COMMAND, 'USAGE_ERROR', agentSelectionError);
  }

  const {
    resolveAgentDevServer,
    buildAgentDevServerHealth,
    registerOwnedDevServerSignalHandlers,
    updateOwnedDevServerHealthOnExit,
    DEFAULT_PORT,
  } = await import('../../index');
  const { startServer } = await import('../../server');
  const { TelemetryService } = await import('../../services/TelemetryService');
  const { createVariantsRuntime } =
    await import('../../services/VariantsRuntime');
  const { findAvailablePort } = await import('../../utils/portUtils');
  const { writeCursorRulesIfNeeded } = await import('../../utils/skillWriter');

  const telemetry = new TelemetryService({
    enabled: flags.values['no-telemetry'] !== true,
    source: 'cli',
  });

  const serverStartStartedAt = Date.now();
  const framework = stringFlag(flags, 'framework') as
    'nextjs' | 'vite' | 'cra' | 'remix' | 'svelte' | 'static' | undefined;
  telemetry.trackServerStartStarted({
    hasFrameworkHint: framework !== undefined,
  });
  let agentDevServer: Awaited<ReturnType<typeof resolveAgentDevServer>>;
  try {
    agentDevServer = await resolveAgentDevServer({
      projectPath,
      options: {
        framework,
        entry: stringFlag(flags, 'entry'),
        userPort: integerFlag(flags, 'user-port'),
      },
    });
  } catch (error) {
    telemetry.trackServerStartFailed({
      stage: 'resolve_dev_server',
      failureReason: 'operation_failed',
      durationMs: Date.now() - serverStartStartedAt,
      error,
    });
    await telemetry.shutdown();
    await logForwarder.shutdown();
    return errorResult(COMMAND, 'SERVER_UNAVAILABLE', errorMessage(error), {
      serverUnavailableReason: 'dev_server_resolution_failed',
    });
  }
  const { project, userDevServerPort, devServerContext } = agentDevServer;

  const library = await ProjectLibrary.open();
  const registeredProject = library.registry.register({ projectPath });
  const hubDiscovery = await HubDiscovery.open(library.registry.root);
  try {
    const variantsRuntime = createVariantsRuntime({
      history: await library.history(registeredProject.id),
      onGeneratedProject: (generatedPath) =>
        library.attachGeneratedRoot({
          projectId: registeredProject.id,
          projectPath: generatedPath,
        }),
      projectPath,
      staticEntry: project.entryPoint,
      telemetry,
      devServerContext,
      devServerHealth: buildAgentDevServerHealth(devServerContext),
    });
    const bridge = variantsRuntime.bridge;
    const sessionInitiator = initiatorFor(handoff);
    const { resolveRunner } = await import('../runnerSelection');
    const { parseCallerRunnerPaths, verifiedRunnerPaths } =
      await import('../callerRunnerPaths');
    const { getConfigManager } = await import('../../services/ConfigManager');
    bridge.setSessionRuntimeInfo({
      sessionInitiator,
      resolvedRunner: resolveRunner({
        explicitAgent: stringFlag(flags, 'agent'),
        configuredRunner: getConfigManager().getConfiguredRunner(),
        handoff,
        runnerPaths: {
          ...parseCallerRunnerPaths(),
          ...verifiedRunnerPaths(
            getConfigManager().getConfiguredRunnerPaths(),
            'config',
          ),
        },
      }),
    });
    try {
      writeSessionHandoff(projectPath, {
        sessionId: bridge.getSessionId(),
        initiator: sessionInitiator,
        handoff,
      });
    } catch (err) {
      io.writeProgress(
        `Could not persist session handoff (non-fatal): ${errorMessage(err)}`,
      );
    }

    if (agentDevServer.ownedProcess) {
      const ownedDevServerPort = devServerContext.port;
      registerOwnedDevServerSignalHandlers(agentDevServer.ownedProcess);
      agentDevServer.ownedProcess.once('exit', (exitCode) => {
        updateOwnedDevServerHealthOnExit(bridge, ownedDevServerPort);
        telemetry.trackDevServerLost({
          port: ownedDevServerPort,
          framework: project.framework,
          exitCode,
        });
      });
    }

    let rivetPort =
      integerFlag(flags, 'rivet-port') ??
      (await findAvailablePort(DEFAULT_PORT));
    let serverStarted = false;
    let retries = 0;
    const maxRetries = 5;
    while (!serverStarted && retries < maxRetries) {
      try {
        const previewPort = await findAvailablePort(rivetPort + 1);
        await startServer({
          userPort: userDevServerPort,
          userHost: project.devServerHost,
          framework: project.framework,
          telemetry,
          projectPath,
          projectId: registeredProject.id,
          staticEntry: project.entryPoint,
          styleFramework: stringFlag(flags, 'style-framework') as
            'tailwind' | undefined,
          tailwindConfig: stringFlag(flags, 'tailwind-config'),
          sessionBridge: bridge,
          variantsRuntime,
          previewPort,
          agentApplyMode: 'external',
          rivetPort,
          resolveProjectName: (targetPath) =>
            library.registry.findByPath(targetPath)?.name,
          resolveLibraryOrigin: () => {
            const hub = hubDiscovery.read();
            return hub?.port && isPidAlive(hub.pid)
              ? `http://localhost:${hub.port}`
              : undefined;
          },
          createLibraryViewUrl: async (view) => {
            const hub = await findHub(library.registry.root);
            if (!hub) return null;
            return createLibraryLaunchUrl({
              hub,
              callerAgent: handoff?.agent,
              path:
                view === 'references'
                  ? '/rivet/library/references'
                  : '/rivet/library',
            });
          },
          beforeShutdown: async () => {
            await agentDevServer.cleanup?.();
            await logForwarder.shutdown();
            library.close();
            hubDiscovery.close();
          },
          restartArgs: [
            '--project',
            projectPath,
            '--rivet-port',
            String(rivetPort),
            '--framework',
            project.framework,
            ...(project.entryPoint ? ['--entry', project.entryPoint] : []),
            ...(devServerContext.ownership === 'external' &&
            userDevServerPort > 0
              ? ['--user-port', String(userDevServerPort)]
              : []),
            ...['style-framework', 'tailwind-config', 'agent'].flatMap(
              (name) => {
                const value = stringFlag(flags, name);
                return value === undefined ? [] : [`--${name}`, value];
              },
            ),
            ...['no-git', 'no-telemetry', 'debug']
              .filter((name) => flags.values[name] === true)
              .map((name) => `--${name}`),
          ],
          cliShutdown: () => process.kill(process.pid, 'SIGTERM'),
        });
        serverStarted = true;
      } catch (err: unknown) {
        const code = (err as { code?: string })?.code;
        if (code === 'EADDRINUSE' && !integerFlag(flags, 'rivet-port')) {
          retries++;
          rivetPort = await findAvailablePort(rivetPort + 1);
        } else {
          await agentDevServer.cleanup?.();
          throw err;
        }
      }
    }

    if (!serverStarted) {
      library.close();
      hubDiscovery.close();
      await agentDevServer.cleanup?.();
      telemetry.trackServerStartFailed({
        stage: 'port_exhausted',
        failureReason: 'port_unavailable',
        durationMs: Date.now() - serverStartStartedAt,
      });
      await telemetry.shutdown();
      await logForwarder.shutdown();
      return errorResult(
        COMMAND,
        'SERVER_UNAVAILABLE',
        `Could not start the Rivet server after ${maxRetries} attempts.`,
        { serverUnavailableReason: 'rivet_port_unavailable' },
      );
    }

    const hasUserDevServer =
      typeof userDevServerPort === 'number' &&
      Number.isInteger(userDevServerPort) &&
      userDevServerPort > 0;
    telemetry.trackServerStarted({
      mode:
        project.framework === 'static' && !hasUserDevServer
          ? 'static'
          : 'attached',
      framework: project.framework,
      hasUserDevServer,
      userDevServerPort,
      ownedDevServer: Boolean(agentDevServer.ownedProcess),
      rivetPort,
      durationMs: Date.now() - serverStartStartedAt,
    });

    if (!getPluginName()) writeCursorRulesIfNeeded(projectPath);

    io.writeProgress(
      `Rivet server on http://localhost:${rivetPort} — variants run via the host agent`,
    );

    await new Promise(() => {});
    return okResult(COMMAND, {});
  } catch (error) {
    hubDiscovery.close();
    library.close();
    await agentDevServer.cleanup?.();
    telemetry.trackServerStartFailed({
      stage: 'start_editor_server',
      failureReason: 'operation_failed',
      durationMs: Date.now() - serverStartStartedAt,
      error,
    });
    await telemetry.shutdown();
    await logForwarder.shutdown();
    return errorResult(COMMAND, 'SERVER_UNAVAILABLE', errorMessage(error), {
      serverUnavailableReason: 'editor_server_start_failed',
    });
  }
};
